package com.wordspring.app.data.seed

import com.wordspring.app.domain.model.BookSourceType
import com.wordspring.app.domain.model.StudyDirection
import kotlinx.serialization.Serializable

/**
 * On-disk metadata for a built-in book: `assets/books/<folder>/metadata.json`.
 * Generated by `tools/build_wordbooks.py` from ECDICT exam tags.
 */
@Serializable
data class StarterBookMetadata(
    val id: String,                  // stable asset id, e.g. "cet4"
    val name: String,                // display name, e.g. "大学英语四级词汇"
    val description: String? = null,
    val sourceType: String = BookSourceType.BUILT_IN.name,
    val dailyNewLimit: Int = 10,
    val license: String,
    val version: String,
    val updatedAt: String,           // ISO date
    val source: String,
    val wordCount: Int,
    val sourceLanguage: String = StudyDirection.SOURCE_LANGUAGE,
    val targetLanguage: String = StudyDirection.TARGET_LANGUAGE
)

/** One meaning group of a word, e.g. pos = "vt.", zh = "放弃；抛弃". */
@Serializable
data class StarterSenseDto(
    val pos: String? = null,
    val zh: String
)

@Serializable
data class StarterEntryDto(
    val word: String,
    val phonetic: String? = null,
    val senses: List<StarterSenseDto> = emptyList(),
    /** ECDICT exchange subset, e.g. "p:ran/d:run/i:running/3:runs". */
    val forms: String? = null,
    // Legacy single-definition format (asset version <= 2.x); still accepted.
    val partOfSpeech: String? = null,
    val definition: String? = null,
    val example: String? = null
) {
    /** Normalised meaning list regardless of which asset format produced this entry. */
    fun resolvedSenses(): List<StarterSenseDto> = when {
        senses.isNotEmpty() -> senses.filter { it.zh.isNotBlank() }
        !definition.isNullOrBlank() -> listOf(StarterSenseDto(partOfSpeech, definition))
        else -> emptyList()
    }
}

@Serializable
data class StarterBookPayload(
    val metadata: StarterBookMetadata,
    val entries: List<StarterEntryDto>
)
